	@ParameterizedTest(name = "{0} [{2}, indexes={3}]")
	@MethodSource("cases")
	void completeAggregate(String name, String query, String strategy, boolean indexed) {
		if (indexed) {
			assertThat(AdjacencyEngagementTestAccess.buildNow((LmdbStore) repository.getSail())).isTrue();
		}
		List<String> expected = rows(query, false, null);
		assertThat(rows(query, true, null)).as("%s automatic parity", name).isEqualTo(expected);
		long before = strategy.equals("irAggregateInterpreted")
				? LmdbNativeKernelExecution.AGG_INTERPRETED_BINDS.get()
				: LmdbNativeKernelExecution.AGG_COMPILED_BINDS.get();
		assertThat(rows(query, true, strategy)).as("%s forced parity", name).isEqualTo(expected);
		long after = strategy.equals("irAggregateInterpreted")
				? LmdbNativeKernelExecution.AGG_INTERPRETED_BINDS.get()
				: LmdbNativeKernelExecution.AGG_COMPILED_BINDS.get();
		assertThat(after).as("%s must bind %s", name, strategy).isGreaterThan(before);
	}

	private List<String> rows(String text, boolean nativeEnabled, String strategy) {
		set(NATIVE, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(PREFIX + text);
			query.setForcedLmdbExecutionStrategy(strategy);
			query.setMaxExecutionTime(15);
			List<String> result = new ArrayList<>();
			for (BindingSet row : QueryResults.asList(query.evaluate())) {
				List<String> bindings = new ArrayList<>();
				for (String name : row.getBindingNames()) {
					String value = row.getValue(name).toString();
					if (name.equals("concat")) {
						// SPARQL does not specify GROUP_CONCAT order; preserve duplicates while comparing its bag.
						String[] parts = ((Literal) row.getValue(name)).getLabel().split("\\|", -1);
						Arrays.sort(parts);
						value = Arrays.toString(parts);
					}
					bindings.add(name + "=" + value);
				}
				bindings.sort(String::compareTo);
				result.add(String.join(";", bindings));
			}
			result.sort(String::compareTo);
			return result;
		}
	}
